def transform(grid):
    n=len(grid)
    # Colors are specified on diagonal bands; the sparse diagonal motif repeats with period n.
    # Detect the diagonal orientation with the most consistent nonzero constraints.
    best=None
    for sign in (1,-1):
        bands={}
        for r,row in enumerate(grid):
            for c,v in enumerate(row):
                if v:
                    k=(r+sign*c)%n
                    bands.setdefault(k,[]).append(v)
        score=sum(len(vs) for vs in bands.values())
        consistency=sum(len(set(vs))==1 for vs in bands.values())
        cand=(consistency,score,sign,bands)
        if best is None or cand[:2]>best[:2]: best=cand
    _,_,sign,bands=best
    seq={k:vs[-1] for k,vs in bands.items()}
    # repeat shortest periodic band sequence compatible with all observed markers
    period=n
    for p in range(1,n+1):
        if n%p==0 and all(seq.get(k)==seq.get(k%p) for k in seq if k%p in seq):
            period=p; break
    out=[]
    for r in range(n):
        row=[]
        for c in range(n):
            row.append(seq.get((r+sign*c)%period,0))
        out.append(row)
    return out
